mapper.select:
${pagingTop} SELECT a.program_list_idx, b.reservation_idx, a.program_name, a.reservation_date, a.reservation_type, a.member_yn, a.use_time, a.notice, a.homepage_id, a.usage_agreement, a.total_people, a.enable_number_of_team, a.maximum_people_of_team, a.add_date, (select count(*) FROM EXP_RESERVATION C where C.program_list_idx = A.program_list_idx AND C.cancel_yn = 'N' AND C.cancel_user_yn = 'N') as apply_count, (select sum(C.application_people) FROM EXP_RESERVATION C where C.program_list_idx = A.program_list_idx AND cancel_yn = 'N' AND C.cancel_user_yn = 'N') as apply_people_count, b.member_id, b.member_name, b.member_phone, b.application_people, b.approve_yn, b.cancel_yn, b.cancel_user_yn, b.reference, b.add_date FROM EXP_PROGRAM_LIST a, EXP_RESERVATION b WHERE a.program_list_idx = b.program_list_idx AND a.homepage_id = b.homepage_id AND b.member_id = #{member_id}
AND b.add_date >= TO_DATE(#{searchDateFrom}, 'YYYY-MM-DD')
AND b.add_date <= TO_DATE(#{searchDateTo}, 'YYYY-MM-DD')+1
ORDER BY a.reservation_date, a.use_time, b.add_date ${pagingBottom}

${pagingTop} SELECT a.program_list_idx, b.reservation_idx, a.program_name, a.reservation_date, a.reservation_type, a.member_yn, a.use_time, a.notice, a.homepage_id, a.usage_agreement, a.total_people, a.enable_number_of_team, a.maximum_people_of_team, a.add_date, (select count(*) FROM EXP_RESERVATION C where C.program_list_idx = A.program_list_idx AND C.cancel_yn = 'N' AND C.cancel_user_yn = 'N') as apply_count, (select sum(C.application_people) FROM EXP_RESERVATION C where C.program_list_idx = A.program_list_idx AND cancel_yn = 'N' AND C.cancel_user_yn = 'N') as apply_people_count, b.member_name, b.member_phone, b.application_people, b.approve_yn, b.cancel_yn, b.cancel_user_yn, b.reference, b.add_date FROM EXP_PROGRAM_LIST a, EXP_RESERVATION b WHERE a.program_list_idx = b.program_list_idx AND a.homepage_id = b.homepage_id AND b.member_name = #{member_name} AND b.member_pw = #{member_pw}
AND b.add_date >= TO_DATE(#{searchDateFrom}, 'YYYY-MM-DD')
AND b.add_date <= TO_DATE(#{searchDateTo}, 'YYYY-MM-DD')+1
ORDER BY a.reservation_date, a.use_time, b.add_date ${pagingBottom}

SELECT
	SUM(application_people) AS totalPeople
FROM
	EXP_RESERVATION
WHERE
	program_list_idx = #{program_list_idx}
AND	homepage_id = #{homepage_id}
AND	cancel_yn = 'N'
AND	cancel_user_yn = 'N'

AND	reservation_idx != #{reservation_idx}

SELECT
	COUNT(*)
FROM
	EXP_RESERVATION
WHERE
	program_list_idx = #{program_list_idx}
AND	homepage_id = #{homepage_id}
AND	cancel_yn = 'N'
AND	cancel_user_yn = 'N'

AND	reservation_idx != #{reservation_idx}

SELECT
	COUNT(*)
FROM
	EXP_RESERVATION
WHERE
	program_list_idx = #{program_list_idx}
AND	homepage_id = #{homepage_id}
AND	member_id = #{member_id}

SELECT COUNT(*) FROM EXP_PROGRAM_LIST a, EXP_RESERVATION b WHERE a.program_list_idx = b.program_list_idx AND a.homepage_id = b.homepage_id AND b.homepage_id = #{homepage_id} AND b.member_id = #{member_id}
AND b.add_date >= TO_DATE(#{searchDateFrom}, 'YYYY-MM-DD')
AND b.add_date <= TO_DATE(#{searchDateTo}, 'YYYY-MM-DD')+1

SELECT COUNT(*) FROM EXP_PROGRAM_LIST a, EXP_RESERVATION b WHERE a.program_list_idx = b.program_list_idx AND a.homepage_id = b.homepage_id AND b.homepage_id = #{homepage_id} AND b.member_name = #{member_name} AND b.member_pw = #{member_pw}
AND b.add_date >= TO_DATE(#{searchDateFrom}, 'YYYY-MM-DD')
AND b.add_date <= TO_DATE(#{searchDateTo}, 'YYYY-MM-DD')+1
